import { CachingService } from "../caching.service";
import { Inject, Injectable } from "@nestjs/common";
import cacheConfig from "../config/caching.config";
import { ConfigType } from "@nestjs/config";
import { CACHE_MANAGER } from "@nestjs/cache-manager";
import { Cache } from "cache-manager";
import Redis from "ioredis";

@Injectable()
export class InfoForQuestCachingService extends CachingService {
	private readonly redisClient: Redis;

	constructor(
		@Inject(cacheConfig.KEY)
		config: ConfigType<typeof cacheConfig>,
		@Inject(CACHE_MANAGER) cacheManager: Cache
	) {
		super(cacheManager, "pin", 60 * 60);
		this.redisClient = new Redis({
			host: "localhost",
			port: 6379,
			password: config.password,
		});
	}

	async scanForPin(): Promise<string> {
		const keys: string[] = [];
		let cursor = "0";

		do {
			const [newCursor, foundKeys] = await this.redisClient.scan(
				cursor,
				"MATCH",
				"pin:*",
				"COUNT",
				100
			);
			cursor = newCursor;

			const numericKeys = foundKeys.filter((key) => /^pin:\d+$/.test(key));

			keys.push(...numericKeys);
		} while (cursor !== "0");

		if (keys.length > 1) {
			const pinsWithTimestamps = await Promise.all(
				keys.map(async (key) => {
					let timestamp = await this.redisClient.get(`${key}:createdAt`)
					timestamp = timestamp.replace(/"/g, "");
					return {key, timestamp: parseInt(timestamp, 10)};
				})
			);
			pinsWithTimestamps.sort((a, b) => b.timestamp - a.timestamp);
			const newest = pinsWithTimestamps[0]?.key;
			return newest ? newest.split(":")[1] : null;
		}
		else
			return keys[0]?.split(":")[1] ?? null;
		//return keys[0];
	}

	async setPin(pin: string, pack: string) {
		await this.set(pin, pack);
		await this.set(`${pin}:createdAt`, Date.now().toString());
	}

	async setProgressID(id: string) {
		await this.set("progressId", id);
	}
	async getProgressID() {
		return await this.get("progressId");
	}

	async setCurrentUserId(id: string) {
		return await this.set("currentUserId", id);
	}
	async getCurrentUserId() {
		return await this.get("currentUserId");
	}

	async setToken(token: string) {
		await this.set("token", token);
	}
	async getToken() {
		return await this.get("token");
	}

	async getTokenID(pin: number) {
		return await this.get(pin.toString());
	}
}